arguments.file_text:
@using sv_ed67d74ca5554236a9bf3c64779c43a4.Services

<div class="message-bubble @(IsThreadRoot ? "thread-root" : "")" @onmouseenter="() => showActions = true" @onmouseleave="HideActions">
    <div class="message-header">
        <strong class="author">@Message.Author</strong>
        <span class="timestamp text-muted">@FormatRelativeTime(Message.SentAt)</span>

        @if (showActions)
        {
            <span class="action-buttons">
                <button class="btn btn-outline-secondary btn-sm" title="Reply" @onclick="() => OnReply.InvokeAsync(Message.Id)">
                    💬
                </button>
                <button class="btn btn-outline-secondary btn-sm" title="React" @onclick="ToggleEmojiPicker">
                    😀
                </button>
            </span>
        }
    </div>

    <div class="message-content">@Message.Content</div>

    @if (Message.Reactions.Count > 0)
    {
        <div class="reactions">
            @foreach (var reaction in Message.Reactions)
            {
                <button class="btn btn-sm reaction-badge" @onclick="() => OnReact.InvokeAsync((Message.Id, reaction.Emoji))">
                    @reaction.Emoji @reaction.Users.Count
                </button>
            }
        </div>
    }

    @if (showEmojiPicker)
    {
        <div class="emoji-picker">
            @foreach (var emoji in commonEmojis)
            {
                <button class="btn btn-sm" @onclick="() => SelectEmoji(emoji)">@emoji</button>
            }
        </div>
    }

    @if (IsThreadRoot && ThreadInfo is not null)
    {
        <button class="btn btn-link btn-sm thread-link" @onclick="() => OnViewThread.InvokeAsync(Message.Id)">
            @ThreadInfo.ReplyCount @(ThreadInfo.ReplyCount == 1 ? "reply" : "replies")
        </button>
    }
</div>

@code {
    [Parameter, EditorRequired] public Message Message { get; set; } = default!;
    [Parameter] public ThreadSummary? ThreadInfo { get; set; }
    [Parameter] public bool IsThreadRoot { get; set; }
    [Parameter] public EventCallback<int> OnReply { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<int> OnViewThread { get; set; }

    private bool showActions;
    private bool showEmojiPicker;
    private static readonly string[] commonEmojis = ["👍", "❤️", "😂", "🎉", "🤔", "👀"];

    private void ToggleEmojiPicker() => showEmojiPicker = !showEmojiPicker;

    private async Task SelectEmoji(string emoji)
    {
        showEmojiPicker = false;
        await OnReact.InvokeAsync((Message.Id, emoji));
    }

    private void HideActions()
    {
        showActions = false;
        showEmojiPicker = false;
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;
        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }
}

.message-bubble {
    padding: 0.5rem 0.75rem;
    border-radius: 6px;
    position: relative;
    transition: background-color 0.15s;
}

.message-bubble:hover {
    background-color: #f8f9fa;
}

.message-header {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 0.2rem;
}

.author {
    font-size: 0.9rem;
}

.timestamp {
    font-size: 0.75rem;
}

.action-buttons {
    margin-left: auto;
    display: flex;
    gap: 0.25rem;
}

.action-buttons button {
    font-size: 0.75rem;
    padding: 0.1rem 0.35rem;
    line-height: 1;
}

.message-content {
    font-size: 0.9rem;
    line-height: 1.45;
    white-space: pre-wrap;
    word-break: break-word;
}

.reactions {
    display: flex;
    flex-wrap: wrap;
    gap: 0.3rem;
    margin-top: 0.35rem;
}

.reaction-badge {
    background: #e9ecef;
    border: 1px solid #dee2e6;
    border-radius: 12px;
    font-size: 0.8rem;
    padding: 0.1rem 0.5rem;
    cursor: pointer;
}

.reaction-badge:hover {
    background: #d4d8dc;
}

.emoji-picker {
    display: flex;
    gap: 0.2rem;
    padding: 0.35rem;
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.12);
    position: absolute;
    right: 0.5rem;
    z-index: 10;
}

.emoji-picker button {
    font-size: 1.1rem;
    padding: 0.15rem 0.3rem;
    line-height: 1;
}

.thread-link {
    font-size: 0.8rem;
    padding: 0;
    text-decoration: none;
    color: #0d6efd;
}

.thread-link:hover {
    text-decoration: underline;
}

