+        <div class="emoji-picker">
+            @foreach (var emoji in commonEmojis)
+            {
+                <button class="btn btn-sm" @onclick="() => SelectEmoji(emoji)">@emoji</button>
+            }
+        </div>
+    }
+
+    @if (IsThreadRoot && ThreadInfo is not null)
+    {
+        <button class="btn btn-link btn-sm thread-link" @onclick="() => OnViewThread.InvokeAsync(Message.Id)">
+            @ThreadInfo.ReplyCount @(ThreadInfo.ReplyCount == 1 ? "reply" : "replies")
+        </button>
+    }
+</div>
+
+@code {
+    [Parameter, EditorRequired] public Message Message { get; set; } = default!;
+    [Parameter] public ThreadSummary? ThreadInfo { get; set; }
+    [Parameter] public bool IsThreadRoot { get; set; }
+    [Parameter] public EventCallback<int> OnReply { get; set; }
+    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
+    [Parameter] public EventCallback<int> OnViewThread { get; set; }
+
+    private bool showActions;
