toolArgs.file_text:
.message-bubble {
    padding: 0.5rem 0.75rem;
    border-radius: 6px;
    position: relative;
    transition: background-color 0.15s;
}

.message-bubble:hover {
    background-color: #f8f9fa;
}

.message-header {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 0.2rem;
}

.author {
    font-size: 0.9rem;
}

.timestamp {
    font-size: 0.75rem;
}

.action-buttons {
    margin-left: auto;
    display: flex;
    gap: 0.25rem;
}

.action-buttons button {
    font-size: 0.75rem;
    padding: 0.1rem 0.35rem;
    line-height: 1;
}

.message-content {
    font-size: 0.9rem;
    line-height: 1.45;
    white-space: pre-wrap;
    word-break: break-word;
}

.reactions {
    display: flex;
    flex-wrap: wrap;
    gap: 0.3rem;
    margin-top: 0.35rem;
}

.reaction-badge {
    background: #e9ecef;
    border: 1px solid #dee2e6;
    border-radius: 12px;
    font-size: 0.8rem;
    padding: 0.1rem 0.5rem;
    cursor: pointer;
}

.reaction-badge:hover {
    background: #d4d8dc;
}

.emoji-picker {
    display: flex;
    gap: 0.2rem;
    padding: 0.35rem;
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.12);
    position: absolute;
    right: 0.5rem;
    z-index: 10;
}

.emoji-picker button {
    font-size: 1.1rem;
    padding: 0.15rem 0.3rem;
    line-height: 1;
}

.thread-link {
    font-size: 0.8rem;
    padding: 0;
    text-decoration: none;
    color: #0d6efd;
}

.thread-link:hover {
    text-decoration: underline;
}

