arguments.file_text:
@using sv_ed67d74ca5554236a9bf3c64779c43a4.Services

<div class="channel-sidebar">
    <div class="sidebar-header">
        <h5>Channels</h5>
    </div>
    <div class="channel-list">
        @foreach (var channel in Channels)
        {
            <button class="channel-item @(channel.Id == SelectedChannelId ? "active" : "")"
                    @onclick="() => OnChannelSelected.InvokeAsync(channel.Id)">
                <div class="channel-name-row">
                    <span class="channel-name"># @channel.Name</span>
                    @if (channel.UnreadCount > 0)
                    {
                        <span class="badge bg-primary rounded-pill">@channel.UnreadCount</span>
                    }
                </div>
                <div class="channel-desc text-muted">@TruncateDescription(channel.Description)</div>
            </button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<Channel> Channels { get; set; } = [];
    [Parameter] public int SelectedChannelId { get; set; }
    [Parameter] public EventCallback<int> OnChannelSelected { get; set; }

    private static string TruncateDescription(string desc)
        => desc.Length > 40 ? string.Concat(desc.AsSpan(0, 40), "…") : desc;
}

.channel-sidebar {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #2c2f33;
    color: #dcddde;
    overflow: hidden;
}

.sidebar-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #40444b;
}

.sidebar-header h5 {
    margin: 0;
    font-size: 1rem;
    color: #fff;
}

.channel-list {
    flex: 1;
    overflow-y: auto;
    padding: 0.5rem 0;
}

.channel-item {
    display: block;
    width: 100%;
    text-align: left;
    background: none;
    border: none;
    padding: 0.5rem 1rem;
    color: #8e9297;
    cursor: pointer;
    transition: background 0.15s;
}

.channel-item:hover {
    background: #36393f;
    color: #dcddde;
}

.channel-item.active {
    background: #40444b;
    color: #fff;
}

.channel-name-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.channel-name {
    font-weight: 600;
    font-size: 0.9rem;
}

.channel-desc {
    font-size: 0.75rem;
    margin-top: 0.15rem;
    color: #72767d !important;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

