@using sv_ed67d74ca5554236a9bf3c64779c43a4.Services

<div class="message-area">
    <div class="area-header">
        <h5># @Channel.Name</h5>
        <span class="text-muted">@Channel.Description</span>
    </div>

    <div class="message-list" @onscroll="HandleScroll" @ref="messageListRef">
        @if (isLoadingMore)
        {
            <div class="text-center py-2">
                <span class="spinner-border spinner-border-sm" role="status"></span>
                Loading…
            </div>
        }

        @if (!HasMore && Messages.Count > 0)
        {
            <div class="text-center text-muted py-2" style="font-size: 0.8rem;">Beginning of conversation</div>
        }

        @foreach (var message in Messages)
        {
            var thread = ThreadSummaries.FirstOrDefault(t => t.RootMessageId == message.Id);
            <MessageBubble Message="message"
                           IsThreadRoot="@(thread is not null)"
                           ThreadInfo="thread"
                           OnReply="OnReply"
                           OnReact="OnReact"
                           OnViewThread="OnViewThread" />
        }
    </div>

    <MessageInput Placeholder="@($"Message #{Channel.Name}")" ButtonText="Send" OnSubmit="OnSend" />
</div>

@code {
    [Parameter, EditorRequired] public Channel Channel { get; set; } = default!;
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public List<ThreadSummary> ThreadSummaries { get; set; } = [];
    [Parameter] public bool HasMore { get; set; }
    [Parameter] public EventCallback<string> OnSend { get; set; }
    [Parameter] public EventCallback<int> OnReply { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<int> OnViewThread { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }

    private ElementReference messageListRef;
    private bool isLoadingMore;

    private async Task HandleScroll()
    {
        if (!HasMore || isLoadingMore) return;

        // Trigger load-more when scrolled near top (handled via JS interop or simple flag)
        isLoadingMore = true;
        await OnLoadMore.InvokeAsync();
        isLoadingMore = false;
    }
}

