.area-header h5 {
    margin: 0 0 0.15rem;
    font-size: 1rem;
}

.area-header span {
    font-size: 0.8rem;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 0.5rem 0;
}

