arguments.file_text:
@using sv_ed67d74ca5554236a9bf3c64779c43a4.Services

<div class="thread-panel">
    <div class="thread-header">
        <h6>Thread</h6>
        <button class="btn btn-sm btn-outline-secondary" @onclick="OnClose" title="Close thread">✕</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root-quote">
            <strong>@RootMessage.Author</strong>
            <p>@RootMessage.Content</p>
        </div>
    }

    <div class="thread-replies">
        @foreach (var reply in Replies)
        {
            <MessageBubble Message="reply"
                           IsThreadRoot="false"
                           OnReply="@(_ => {})"
                           OnReact="OnReact"
                           OnViewThread="@(_ => {})" />
        }
