@page "/chat"
@rendermode InteractiveServer
@using sv_ed67d74ca5554236a9bf3c64779c43a4.Services
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="chat-sidebar">
        <ChannelSidebar Channels="channels"
                        SelectedChannelId="selectedChannelId"
                        OnChannelSelected="SelectChannel" />
    </div>

    <div class="chat-main @(threadOpen ? "with-thread" : "")">
        @if (selectedChannel is not null)
        {
            <MessageArea Channel="selectedChannel"
                         Messages="messages"
                         ThreadSummaries="threadSummaries"
                         HasMore="hasMore"
                         OnSend="SendMessage"
                         OnReply="OpenThread"
                         OnReact="AddReaction"
                         OnViewThread="OpenThread"
                         OnLoadMore="LoadMoreMessages" />
        }
        else
        {
            <div class="d-flex align-items-center justify-content-center h-100 text-muted">
                Select a channel to start chatting
            </div>
        }
    </div>

    @if (threadOpen)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="threadRootMessage"
                         Replies="threadReplies"
                         OnClose="CloseThread"
                         OnReply="SendThreadReply"
                         OnReact="AddReaction" />
        </div>
    }
</div>

@code {
    private const int PageSize = 30;

    private List<Channel> channels = [];
    private int selectedChannelId;
    private Channel? selectedChannel;
    private List<Message> messages = [];
    private List<ThreadSummary> threadSummaries = [];
    private bool hasMore = true;

    // Thread state
    private bool threadOpen;
    private int threadRootId;
    private Message? threadRootMessage;
    private List<Message> threadReplies = [];

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        selectedChannelId = channelId;
        selectedChannel = channels.FirstOrDefault(c => c.Id == channelId);
        messages = [];
        hasMore = true;
        CloseThread();

        var loaded = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        messages = loaded;
        hasMore = loaded.Count >= PageSize;

        BuildThreadSummaries();
        await ChatService.MarkChannelReadAsync(channelId);

        // Refresh channel list to update unread counts
        channels = await ChatService.GetChannelsAsync();
    }

    private async Task LoadMoreMessages()
    {
        if (!hasMore || selectedChannel is null) return;

        var older = await ChatService.GetMessagesAsync(selectedChannelId, messages.Count, PageSize);
        if (older.Count < PageSize) hasMore = false;

        // Prepend older messages
        messages.InsertRange(0, older);
        BuildThreadSummaries();
    }

    private async Task SendMessage(string content)
    {
        if (selectedChannel is null) return;
        var msg = await ChatService.SendMessageAsync(selectedChannelId, content, null);
        messages.Add(msg);
    }

    private async Task OpenThread(int rootMessageId)
    {
        threadRootId = rootMessageId;
        threadRootMessage = messages.FirstOrDefault(m => m.Id == rootMessageId);
        threadReplies = await ChatService.GetThreadAsync(rootMessageId);
        threadOpen = true;
    }

    private void CloseThread()
    {
        threadOpen = false;
        threadRootMessage = null;
        threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (selectedChannel is null) return;
        var reply = await ChatService.SendMessageAsync(selectedChannelId, content, threadRootId);
        threadReplies.Add(reply);
        BuildThreadSummaries();
    }

    private async Task AddReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Refresh messages to reflect updated reactions
        if (selectedChannel is not null)
        {
            messages = await ChatService.GetMessagesAsync(selectedChannelId, 0, messages.Count);
        }

        if (threadOpen)
        {
            threadReplies = await ChatService.GetThreadAsync(threadRootId);
        }
    }

    private void BuildThreadSummaries()
    {
        // Build thread summaries from messages that have replies pointing to them
        var rootIds = messages
            .Where(m => m.ReplyToId is not null)
            .Select(m => m.ReplyToId!.Value)
            .Distinct()
            .ToList();

        threadSummaries = rootIds
            .Select(rootId =>
            {
                var replies = messages.Where(m => m.ReplyToId == rootId).ToList();
                return new ThreadSummary(rootId, replies.Count, replies.Max(r => r.SentAt));
            })
            .ToList();
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
}

.chat-sidebar {
    width: 20%;
    min-width: 200px;
    flex-shrink: 0;
}

.chat-main {
    flex: 1;
    min-width: 0;
    transition: flex 0.2s ease;
}

.chat-main.with-thread {
    flex: 0 0 55%;
}

.chat-thread {
    width: 25%;
    min-width: 250px;
    flex-shrink: 0;
}

